<?php declare(strict_types=1);namespace StudPulse\Integrations;use StudPulse\Bars\BarsTeacherDirectory;use StudPulse\Config;use StudPulse\Http\ApiError;final class HttpClient{private const HOSTS=['oauth2.googleapis.com','www.googleapis.com','ts.mpei.ru'];public static function request(string$method,string$url,array$headers=[],?string$body=null):array{$host=parse_url($url,PHP_URL_HOST);$directory=$method==='GET'&&str_starts_with($url,BarsTeacherDirectory::URL.'?');if(parse_url($url,PHP_URL_SCHEME)!=='https'||(!$directory&&!in_array($host,self::HOSTS,true))||parse_url($url,PHP_URL_USER)!==null){throw new \RuntimeException('Outbound destination denied');}$dir=Config::storage().'/circuits';if(!is_dir($dir)){mkdir($dir,0700,true);}$path=$dir.'/'.hash('sha256',$host).'.json';$state=is_file($path)?json_decode(file_get_contents($path),true):[];if(($state['until']??0)>time()){throw new ApiError(503,'PROVIDER_CIRCUIT_OPEN','Внешний сервис временно недоступен');}$attempts=$method==='GET'&&!$directory&&$host!=='ts.mpei.ru'?3:1;for($attempt=0;$attempt<$attempts;$attempt++){$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CUSTOMREQUEST=>$method,CURLOPT_HTTPHEADER=>$headers,CURLOPT_CONNECTTIMEOUT=>4,CURLOPT_TIMEOUT=>12,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_PROTOCOLS=>CURLPROTO_HTTPS,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2,CURLOPT_MAXFILESIZE=>2097152]);$buffer='';curl_setopt($ch,CURLOPT_WRITEFUNCTION,static function($handle,string$chunk)use(&$buffer):int{if(strlen($buffer)+strlen($chunk)>2097152){return 0;}$buffer.=$chunk;return strlen($chunk);});if($body!==null){curl_setopt($ch,CURLOPT_POSTFIELDS,$body);}$completed=curl_exec($ch);$raw=$completed===false?false:$buffer;$status=(int)curl_getinfo($ch,CURLINFO_RESPONSE_CODE);curl_close($ch);if($raw!==false&&$status>=200&&$status<300){file_put_contents($path,json_encode(['failures'=>0,'until'=>0]),LOCK_EX);return['status'=>$status,'raw'=>$raw,'json'=>json_decode($raw,true)];}if(in_array($status,[400,401,403,404,409],true)){if($host==='oauth2.googleapis.com'&&$status===400&&(json_decode($buffer,true)['error']??null)==='invalid_grant'){throw new ApiError(409,'GOOGLE_INVALID_GRANT','Google отозвал доступ. Подключите Drive снова.');}throw new ApiError($status===401?409:502,$status===401?'GOOGLE_REAUTH_REQUIRED':'PROVIDER_REJECTED','Внешний сервис отклонил запрос. Проверьте подключение и разрешения.');}if($attempt+1<$attempts){usleep((int)((200000*(2**$attempt))+random_int(0,100000)));}}$failures=($state['failures']??0)+1;file_put_contents($path,json_encode(['failures'=>$failures,'until'=>$failures>=3?time()+60:0]),LOCK_EX);throw new ApiError(503,$status===429?'PROVIDER_QUOTA':'PROVIDER_UNAVAILABLE','Внешний сервис недоступен или ограничил частоту запросов');}}